package com.aoo.bcg.gamespi.fsm;
import java.util.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class StateMachineCoverageTest{enum Event{OPEN,LATE}@Test void releaseGateMeasuresThreeIndependentCoverageDimensions(){var legal=new StateMachineCoverage.Edge<>(RoomLifecycleState.CREATED,Event.OPEN);var illegal=new StateMachineCoverage.Edge<>(RoomLifecycleState.FINISHED,Event.LATE);var coverage=new StateMachineCoverage<RoomLifecycleState,Event>(Set.of(RoomLifecycleState.CREATED,RoomLifecycleState.FINISHED),Set.of(legal),Set.of(illegal));coverage.markLegal(legal.state(),legal.event());assertThrows(IllegalStateException.class,()->coverage.requireReleaseThreshold(1,1,1));coverage.markIllegal(illegal.state(),illegal.event());coverage.requireReleaseThreshold(1,1,1);assertEquals(1d,coverage.report().criticalIllegalEdgeCoverage());}}
